# region: render
def render(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs, offset=-1):
    return [v + offset for v in xs[1:]]

# region: gather
def gather(xs, factor=3):
    return [v * factor for v in xs]

# region: fold
def fold(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(fold(gather(intake(render(raw)))))

