        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'total': 3, 'ratio': 1.5})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'total': 18, 'ratio': 1.5})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 6, 'ratio': 1.5})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'total': 0, 'ratio': 0.5})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 0, 'ratio': 2.0})
